function dspError(statusCode, code, reasons) {
    msg.statusCode = statusCode;
    msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': reasons };
    msg.headers = { 'Content-Type': 'application/json' };
    return [msg, null];
}

function timingSafeEqualStr(a, b) {
    const bufA = Buffer.from(String(a), 'utf8');
    const bufB = Buffer.from(String(b), 'utf8');
    if (bufA.length !== bufB.length) return false;
    return crypto.timingSafeEqual(bufA, bufB);
}

const assetId = msg.req.params.assetId;
const q = msg.req.query || {};
const token = q.token || '';
const expiresAt = q.expiresAt || '';
const fromTs = q.from || '';
const toTs = q.to || '';
const agreementId = q.agreementId || '';
const roles = q.roles || '';

const secret = env.get('DSP_HMAC_SECRET');
if (!secret) {
    node.error('dsp-data-verify-fn: DSP_HMAC_SECRET unset');
    return dspError(503, 'signing_not_configured', ['DSP_HMAC_SECRET is not configured']);
}
if (!token || !expiresAt) {
    return dspError(401, 'invalid_token', ['token and expiresAt query params are required']);
}

const path = '/api/data/' + assetId;
const encodedAgreementId = encodeURIComponent(agreementId);
const encodedRoles = encodeURIComponent(roles);
const message = 'GET:' + path + ':' + fromTs + ':' + toTs + ':' + expiresAt + ':' + encodedAgreementId + ':' + encodedRoles;
const expected = crypto.createHmac('sha256', Buffer.from(secret, 'utf8')).update(message, 'utf8').digest('hex');

if (!timingSafeEqualStr(token, expected)) {
    return dspError(401, 'invalid_token', ['HMAC signature does not match']);
}

const expiryMs = Date.parse(expiresAt);
if (!Number.isFinite(expiryMs) || Date.now() > expiryMs) {
    return dspError(401, 'token_expired', ['signed URL expired at ' + expiresAt]);
}

msg._dspDataWindow = { assetId: assetId, from: fromTs, to: toTs, agreementId: agreementId, roles: roles };
return [null, msg];
